          "text": "第三条 财政部门依照本暂行办法对市本级财政性基本建设资金的管理和监督履行下列职责：（一）负责所有用于基本建设项目投资的财政性资金拨付；（二）编制基本建设支出预算；（三）在本级年度基本建设投资项目计划编制过程中就财政性资金安排向发展改革部门提出意见；（四）核查基本建设项目工程预（结）算和竣工财务决算情况；（五）对基本建设项目的财务活动实施全过程的管理和监督。"
