          "title": "资金安排和使用",
          "summary": " 本级年度基本建设投资项目计划和支出预算是财政部门拨付基本建设资金的基本依据。建设单位向财政部门申办基本建设资金拨款时，应提交以下资料：（一）经批准立项和开工的有关文件；（二）设计方案及概算的批准文本；（三）年度基本建设投资项目计划申请表及说明；（四）年度资金",
          "text": "第七条 本级年度基本建设投资项目计划和支出预算是财政部门拨付基本建设资金的基本依据。建设单位向财政部门申办基本建设资金拨款时，应提交以下资料：（一）经批准立项和开工的有关文件；（二）设计方案及概算的批准文本；（三）年度基本建设投资项目计划申请表及说明；（四）年度资金用款计划；（五）工程预算、施工合同、工程进度表及工程监理等部门的签署意见；（六）有其他建设资金来源的项目，须提供配套资金落实情况资料；（七）财政部门要求提供的其他资料。"
