          "title": "资金安排和使用",
          "summary": " 省级政府投资金按项目安排，以直接投资方式为主；对确需支持的经营性项目，主要采取资本金注入方式，也可以适当采取投资补助、贷款贴息等方式。",
          "text": "第六条 省级政府投资金按项目安排，以直接投资方式为主；对确需支持的经营性项目，主要采取资本金注入方式，也可以适当采取投资补助、贷款贴息等方式。"
