          "text": "第一条 为规范深圳市财政性基本建设资金的拨付管理，加强财政监督，保证资金的安全和合理使用，提高资金投资效益，根据《中华人民共和国预算法》《中华人民共和国预算法实施条例》《深圳市政府投资项目管理条例》的有关规定，制定本暂行办法。"
