          "text": "第四条 使用财政性基本建设资金的建设单位（以下简称建设单位）负责本单位基本建设项目的组织实施工作，审核基本建设资金申报的相关资料，进行基本建设资金的会计核算和财务管理，确保基本建设资金的安全和合理使用。基本建设项目主管部门负责本部门基本建设项目的统一规划、申报和协调，协助财政部门加强对基本建设资金的财务管理和监督检查。"
