          "text": "第七条 市发展改⾰委、市财政局会同有关部⻔根据国⺠经济和社会发展规划、中期财政规划、国家宏观调控政策和本市相关政策，结合财政收⽀状况，统筹安排使⽤市级政府投资⾦的项⽬，规范使⽤各类政府投资⾦。第⼋条 市级政府投资项⽬实⾏项⽬储备制，原则上从市级政府投资项⽬储备库中选取。市发展改⾰委会同有关部⻔建⽴市级政府投资项⽬储备库，负责储备项⽬的⼊库、管理和更新⼯作。经市发展改⾰委会同有关部⻔论证和平衡，并报市政府批准的专项规划、专项发展建设规划、产业政策等，是纳⼊市级政府投资项⽬储备库的重要依据。"
