          "summary": " 本办法所称的项目策划生成是指项目单位提出建设意向、开展前期研究论证，初步落实建设条件并明确项目主要技术经济指标的过程。本办法所称项目单位，是指项目建议书、可行性研究报告的组织编制和申报单位。",
          "text": "第二条 本办法所称的项目策划生成是指项目单位提出建设意向、开展前期研究论证，初步落实建设条件并明确项目主要技术经济指标的过程。本办法所称项目单位，是指项目建议书、可行性研究报告的组织编制和申报单位。"
