          "text": "第十五条 需要开展规划调整的，相关部门原则上应当在项目建议书批复后主动开展规划调整。根据相关法律法规定，确需依申请开展的规划调整事项，由项目单位在项目建议书批复后20个工作日内申请启动规划调整等相关工作。"
