          "text": "第四条 项目单位应当提前谋划，并根据国民经济和社会发展五年规划纲要或者经批准的专项规划，提出一定时期内需要建设的政府投资项目，组织开展前期研究工作并按照相关规定的内容和深度编制前期工作成果文件，按程序申报项目策划生成论证。"
