          "text": "第一条 为加强深圳市政府投资项目（以下简称项目）储备，理顺项目前期论证时序，加快推进“多规合一”业务协同，提高项目转化率，根据《政府投资条例》《深圳经济特区政府投资项目管理条例》《深圳市政府投资建设项目施工许可管理规定》（深圳市人民政府令第328号）等法规、规章规定，结合我市实际制定本办法。"
