          "text": "第三条 本办法适用于涉及新增建设用地的新建、改建、扩建类市政府投资项目以及建设规模或功能调整的改建、扩建类市政府投资项目的策划生成阶段管理。国家审批用海（含围填海）项目以及涉及国家秘密的项目不适用本办法。"
