          "text": "第五条 市发展改革部门统筹管理项目策划生成，会同相关部门加强项目储备和动态管理，建立和完善项目协调机制，建设和维护项目登记平台，依托项目登记平台受理项目策划生成论证申报并开展项目策划生成论证。市规划和自然资源部门牵头负责项目空间协调，依托“多规合一”信息平台（以下简称多规平台）提供项目空间信息查询、空间论证、空间规划协调等支撑服务，负责多规平台的建设维护、运行管理和监督。生态环境、水务、交通、住建等相关部门负责本部门空间性规划及相关信息的及时共享和更新，保证相关数据的准确性、真实性和合法性，并按相关法律、法规和本办法要求开展项目空间论证等工作。"
