          "text": "第十五条 规划和自然资源部门及其派出机构的建设工程设计方案核查、地名批复（建筑物命名核准/公共设施名称核准/专业设施名称核查及备案）与建设工程规划许可事项合并办理，分别核发相关证件；开设永久路口审批与市政管线接口审批合并办理，分别核发相关证件。交通运输部门不再办理开设永久路口审批及交通影响评价。占用挖掘道路、开设临时路口由交通运输部门和公安交警部门从产权管理和交通秩序管理方面分别进行办理，统一出证。"
