          "text": "第五条 市政务服务数据管理部门负责投资项目在线审批监管平台（工程建设项目管理系统，以下简称在线平台）的建设、运行维护和数据管理。在线平台是建设项目施工许可相关事项跨部门协同办理的平台，并作为广东政务服务网深圳行政区域的在线办理系统。在线平台应当满足审批部门、建设单位、中介机构等多方使用单位共同应用和数据共享的要求，各部门审批系统与在线平台对接，数据双向实时流转，在线平台实现审批事项、受理材料、批复文件、流转信息等的强制共享、结果互认，实现项目建设的全流程覆盖、全业务流转、全方位监管。"
