          "text": "第六条 市规划和自然资源部门建立“多规合一”信息平台（以下简称多规平台），整合全市国民经济和社会发展、规划国土、交通运输、生态环境、海洋、林业、水务、气象、海绵城市、综合管廊等各领域空间性规划和相关信息，形成全市空间规划“一张蓝图”，为项目空间论证、策划生成提供平台支撑，不断提高“一张蓝图”统筹项目实施效率。各相关部门应当按照要求汇交、共享协调一致后的空间性规划和相关信息，保证相关数据的及时性、准确性、真实性、合法性、安全性，涉及空间性规划管控条件的，应当提供相应的管控内容、核查规则、法律依据等。"
